-- A rate saved with a from-date on or after the sheet's today is forward-only: it applies only to
-- claims added after it was saved. Claims and forward-only rates take their place in one order from
-- claim_added_seq: a claim takes the next when it is added (a moved, copied or split-off claim keeps
-- its own), a forward-only rate (and each of its versions) the next when it is saved, and a claim
-- sees a forward-only rate only when its place is after the rate's. Claims already stored come first.
CREATE SEQUENCE claim_added_seq START WITH 1;
ALTER TABLE claim ADD COLUMN added BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE rate ADD COLUMN forward_after BIGINT;
ALTER TABLE rate_version ADD COLUMN forward_after BIGINT;
ALTER TABLE rate_revision ADD COLUMN forward_after BIGINT;
ALTER TABLE claim_revision ADD COLUMN added BIGINT DEFAULT 0 NOT NULL;
package net.officefloor.hq.app.watch;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A user watching a person on a sheet: they are told when the person's claims are settled. */
@Entity
@Table(name = "person_watch")
public class Watch {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "user_name", nullable = false)
    private String user;

    /** The sheet's today when the user started watching; null for one started before it was kept. */
    @Column(name = "started_on")
    private LocalDate startedOn;

    protected Watch() {
    }

    public Watch(String sheetId, Long personId, String user, LocalDate startedOn) {
        this.startedOn = startedOn;
        this.sheetId = sheetId;
        this.personId = personId;
        this.user = user;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public String getUser() {
        return user;
    }

    public LocalDate getStartedOn() {
        return startedOn;
    }
}
package net.officefloor.hq.app.watch;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface WatchRepository extends JpaRepository<Watch, Long> {

    /** The people a user watches on a sheet, in the order they started watching. */
    List<Watch> findBySheetIdAndUserOrderByIdAsc(String sheetId, String user);

    /** The users watching a person, in the order they started watching. */
    List<Watch> findByPersonIdOrderByIdAsc(Long personId);

    Optional<Watch> findByPersonIdAndUser(Long personId, String user);
}
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
